import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
// --- Schema Definition ---


export type FormulaERaceTrackProps = Record<string, any>;

// --- Track Precomputation ---
// We precompute the track path, lengths, and arrow placements once outside the render cycle
// to ensure perfect performance and anti-flicker compliance.

// 1. Raw layout points resembling a complex Formula E street circuit
const RAW_KEYPOINTS = [
  { x: 300, y: 700 }, // start finish straight
  { x: 200, y: 700 },
  { x: 100, y: 650 }, // sharp U-turn left
  { x: 100, y: 600 },
  { x: 200, y: 580 }, // snake back right
  { x: 350, y: 620 },
  { x: 450, y: 550 },
  { x: 500, y: 450 }, // straight up
  { x: 600, y: 400 },
  { x: 800, y: 380 }, // long straight top
  { x: 1100, y: 380 },
  { x: 1150, y: 350 }, // chicane
  { x: 1200, y: 380 },
  { x: 1400, y: 350 },
  { x: 1500, y: 300 }, // chicane
  { x: 1550, y: 350 },
  { x: 1750, y: 300 }, // right hairpin
  { x: 1800, y: 350 },
  { x: 1750, y: 450 }, // down and back left
  { x: 1500, y: 650 },
  { x: 1300, y: 750 },
  { x: 1100, y: 800 },
  { x: 1000, y: 750 }, // slight bump
  { x: 900, y: 800 },
  { x: 700, y: 750 },
  { x: 500, y: 650 },
  { x: 400, y: 700 } // back to start
];

// 2. Catmull-Rom spline generator for smooth curves
function getCatmullRomPoint(t: number, p0: {x: number, y: number}, p1: {x: number, y: number}, p2: {x: number, y: number}, p3: {x: number, y: number}) {
  const t2 = t * t;
  const t3 = t2 * t;
  const x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
  const y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);
  return {x, y};
}

const SAMPLED: {x: number, y: number}[] = [];
const NUM_SAMPLES = 20; // smoothness
for (let i = 0; i < RAW_KEYPOINTS.length; i++) {
  const p0 = RAW_KEYPOINTS[(i - 1 + RAW_KEYPOINTS.length) % RAW_KEYPOINTS.length];
  const p1 = RAW_KEYPOINTS[i];
  const p2 = RAW_KEYPOINTS[(i + 1) % RAW_KEYPOINTS.length];
  const p3 = RAW_KEYPOINTS[(i + 2) % RAW_KEYPOINTS.length];
  for(let j = 0; j < NUM_SAMPLES; j++) {
    SAMPLED.push(getCatmullRomPoint(j / NUM_SAMPLES, p0, p1, p2, p3));
  }
}

// 3. Center the track perfectly within a 1920x1080 canvas
let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
SAMPLED.forEach(p => {
  if (p.x < minX) minX = p.x;
  if (p.x > maxX) maxX = p.x;
  if (p.y < minY) minY = p.y;
  if (p.y > maxY) maxY = p.y;
});
const cx = (minX + maxX) / 2;
const cy = (minY + maxY) / 2;
const dx = 1920 / 2 - cx;
const dy = 1080 / 2 - cy;

const FINAL_SAMPLED = SAMPLED.map(p => ({ x: p.x + dx, y: p.y + dy }));
const FINAL_KEYPOINTS = RAW_KEYPOINTS.map(p => ({ x: p.x + dx, y: p.y + dy }));

// 4. Calculate distances for deterministic movement
const DISTANCES = [0];
let TOTAL_LENGTH = 0;
for (let i = 1; i < FINAL_SAMPLED.length; i++) {
  const dist = Math.hypot(FINAL_SAMPLED[i].x - FINAL_SAMPLED[i-1].x, FINAL_SAMPLED[i].y - FINAL_SAMPLED[i-1].y);
  TOTAL_LENGTH += dist;
  DISTANCES.push(TOTAL_LENGTH);
}
// Close the loop distance
const dLast = Math.hypot(FINAL_SAMPLED[0].x - FINAL_SAMPLED[FINAL_SAMPLED.length-1].x, FINAL_SAMPLED[0].y - FINAL_SAMPLED[FINAL_SAMPLED.length-1].y);
TOTAL_LENGTH += dLast;
DISTANCES.push(TOTAL_LENGTH);

const CLOSED_POINTS = [...FINAL_SAMPLED, FINAL_SAMPLED[0]];

// 5. Position interpolation helper (Distance-based)
function getRawTrackTransform(D: number) {
  D = ((D % TOTAL_LENGTH) + TOTAL_LENGTH) % TOTAL_LENGTH;
  let idx = 1;
  while(idx < DISTANCES.length && DISTANCES[idx] < D) {
    idx++;
  }
  if (idx >= DISTANCES.length) idx = DISTANCES.length - 1;

  const p1 = CLOSED_POINTS[idx-1];
  const p2 = CLOSED_POINTS[idx];
  const d1 = DISTANCES[idx-1];
  const d2 = DISTANCES[idx];
  const progress = (D - d1) / (d2 - d1 || 1);

  const x = p1.x + (p2.x - p1.x) * progress;
  const y = p1.y + (p2.y - p1.y) * progress;
  const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);

  return { x, y, angle };
}

// 6. Precompute Time -> Distance mapping to allow variable speed (slowing down around turns)
const TIME_STEPS = [0];
const DIST_STEPS = [0];
let current_time = 0;
const STEP_SIZE = 5;

for (let d = STEP_SIZE; d <= TOTAL_LENGTH; d += STEP_SIZE) {
  const lookBack = getRawTrackTransform(d - 60);
  const lookAhead = getRawTrackTransform(d + 60);
  
  let diff = lookAhead.angle - lookBack.angle;
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;
  
  const curvature = Math.abs(diff);
  // Curve mapping: slow down on sharp turns (max ~75% speed reduction)
  const speedFactor = Math.max(0.25, 1.0 - curvature * 0.4); 
  
  current_time += STEP_SIZE / speedFactor;
  TIME_STEPS.push(current_time);
  DIST_STEPS.push(d);
}

// Add final exact point to close the time loop
if (DIST_STEPS[DIST_STEPS.length - 1] < TOTAL_LENGTH) {
  const d = TOTAL_LENGTH;
  const lookBack = getRawTrackTransform(d - 60);
  const lookAhead = getRawTrackTransform(d + 60);
  
  let diff = lookAhead.angle - lookBack.angle;
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;
  
  const curvature = Math.abs(diff);
  const speedFactor = Math.max(0.25, 1.0 - curvature * 0.4); 
  
  const step = d - DIST_STEPS[DIST_STEPS.length - 1];
  current_time += step / speedFactor;
  TIME_STEPS.push(current_time);
  DIST_STEPS.push(d);
}
const TOTAL_TIME = current_time;

// Helper to get distance from integrated time
function getDistanceForTime(T: number) {
  T = ((T % TOTAL_TIME) + TOTAL_TIME) % TOTAL_TIME;
  let idx = 1;
  while (idx < TIME_STEPS.length && TIME_STEPS[idx] < T) {
    idx++;
  }
  if (idx >= TIME_STEPS.length) idx = TIME_STEPS.length - 1;
  
  const t1 = TIME_STEPS[idx-1];
  const t2 = TIME_STEPS[idx];
  const d1 = DIST_STEPS[idx-1];
  const d2 = DIST_STEPS[idx];
  
  const progress = (T - t1) / (t2 - t1 || 1);
  return d1 + (d2 - d1) * progress;
}

// Time-based transformation function for dynamic car speed
function getTrackTransform(T: number) {
  const dist = getDistanceForTime(T);
  return getRawTrackTransform(dist);
}

// 7. Precompute Track Arrows & Braking Zones based on raw distance
const ARROWS: {x: number, y: number, angle: number, isBraking: boolean}[] = [];
const ARROW_SPACING = 90;
for (let d = 0; d < TOTAL_LENGTH; d += ARROW_SPACING) {
  const current = getRawTrackTransform(d);
  const lookahead = getRawTrackTransform(d + 150); // Look 150px ahead for corners
  
  let diff = lookahead.angle - current.angle;
  // Normalize angular difference to [-PI, PI]
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;

  // If the track bends more than ~34 degrees ahead, it's a braking zone
  const isBraking = Math.abs(diff) > 0.6; 
  
  ARROWS.push({
    x: current.x,
    y: current.y,
    // Reverse arrow direction if braking
    angle: isBraking ? current.angle + Math.PI : current.angle,
    isBraking
  });
}

// 8. Generate SVG Path string
const PATH_DATA = `M ${CLOSED_POINTS[0].x} ${CLOSED_POINTS[0].y} ` + 
  CLOSED_POINTS.slice(1).map(p => `L ${p.x} ${p.y}`).join(' ') + " Z";


// --- Component ---
const FormulaERaceTrack: React.FC<FormulaERaceTrackProps> = ({
  backgroundColor = "#f5f5f7",
  transparentBackground = false,
  durationInSeconds = 15,
  trackColor = "#0022FF",
  carColor = "#FF0055",
  carSpeed = 12,
  startPosition = 0.0,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling to fit the 1920x1080 coordinate system into any canvas
  const scale = useMemo(() => Math.min(width / 1920, height / 1080) * 0.9, [width, height]);
  
  // Calculate current car position using integrated time for variable speed around turns
  const startTime = startPosition * TOTAL_TIME;
  const currentTime = startTime + (frame * carSpeed);
  const carTransform = getTrackTransform(currentTime);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* Container scaled and centered to fit window */}
      <div style={{
        position: 'absolute',
        width: 1920,
        height: 1080,
        left: '50%',
        top: '50%',
        transform: `translate(-50%, -50%) scale(${scale})`,
        transformOrigin: 'center center',
      }}>
        
        {/* Static Track Graphics */}
        <svg width="1920" height="1080" style={{ overflow: 'visible', position: 'absolute', left: 0, top: 0 }}>
          {/* Track Drop Shadow */}
          <path 
            d={PATH_DATA} 
            fill="none" 
            stroke="rgba(0, 0, 0, 0.25)" 
            strokeWidth={16} 
            transform="translate(12, 16)" 
            strokeLinejoin="round" 
            strokeLinecap="round" 
          />
          
          {/* Main Track Line */}
          <path 
            d={PATH_DATA} 
            fill="none" 
            stroke={trackColor} 
            strokeWidth={14} 
            strokeLinejoin="round" 
            strokeLinecap="round" 
          />

          {/* Keypoint Track Markers (Grey Nodes) */}
          {FINAL_KEYPOINTS.map((pt, i) => (
            <circle 
              key={`node-${i}`} 
              cx={pt.x} 
              cy={pt.y} 
              r="7" 
              fill="#555" 
              stroke="rgba(0,0,0,0.3)" 
              strokeWidth="2" 
            />
          ))}

          {/* Directional & Braking Arrows */}
          {ARROWS.map((arrow, i) => (
            <g 
              key={`arrow-${i}`} 
              transform={`translate(${arrow.x}, ${arrow.y}) rotate(${(arrow.angle * 180) / Math.PI})`}
            >
              <path 
                d="M -3 -4 L 3 0 L -3 4" 
                fill="none" 
                stroke={arrow.isBraking ? "#ff4444" : "rgba(255, 255, 255, 0.85)"} 
                strokeWidth="2.5" 
                strokeLinecap="round" 
                strokeLinejoin="round"
              />
            </g>
          ))}
        </svg>

        {/* Dynamic Animated Car */}
        <div style={{
          position: 'absolute',
          left: carTransform.x,
          top: carTransform.y,
          width: 44,
          height: 22,
          transform: `translate(-50%, -50%) rotate(${carTransform.angle}rad)`,
          filter: 'drop-shadow(4px 6px 4px rgba(0,0,0,0.4))',
          willChange: 'transform',
        }}>
          {/* Top-down Formula E Car SVG */}
          <svg width="44" height="22" viewBox="0 0 44 22" style={{ overflow: 'visible' }}>
            {/* Tires */}
            <rect x="28" y="-1" width="10" height="5" fill="#111" rx="1.5" />
            <rect x="28" y="18" width="10" height="5" fill="#111" rx="1.5" />
            <rect x="6" y="-1" width="10" height="5" fill="#111" rx="1.5" />
            <rect x="6" y="18" width="10" height="5" fill="#111" rx="1.5" />

            {/* Suspension / Axles */}
            <path d="M 11 4 L 16 11 L 11 18" stroke="#333" strokeWidth="1.5" fill="none"/>
            <path d="M 33 4 L 28 11 L 33 18" stroke="#333" strokeWidth="1.5" fill="none"/>

            {/* Main Chassis Body */}
            <path d="M 38 11 L 28 7 L 12 7 L 6 9 L 6 13 L 12 15 L 28 15 Z" fill={carColor} />

            {/* Wide Sidepods */}
            <rect x="12" y="5" width="14" height="12" fill={carColor} rx="2" />

            {/* Front Wing Assembly */}
            <path d="M 42 4 L 42 18 L 38 15 L 38 7 Z" fill="#222" />
            <rect x="38" y="10" width="4" height="2" fill={carColor} />

            {/* Rear Wing Assembly */}
            <path d="M 2 2 L 6 2 L 6 20 L 2 20 Z" fill="#222" />
            <rect x="0" y="5" width="5" height="12" fill={carColor} />

            {/* Cockpit and Driver Halo */}
            <circle cx="20" cy="11" r="3" fill="#111" />
            <path d="M 23 11 L 18 9 L 18 13 Z" fill="#444" />
          </svg>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default FormulaERaceTrack;